            .ToList();

        Assert.True(etapa7Segments.Count > 0,
            $"[{scenarioId}] Nenhum segmento com etapas=[..7..] encontrado.");

        // (b) Segmentos ordenados por ordemNaJornada
        int prevOrdem = -1;
        foreach (var seg in etapa7Segments)
        {
            Assert.True(seg.OrdemNaJornada >= prevOrdem,
                $"[{scenarioId}] Segmento etapa 7 fora de ordem: " +
                $"ordemNaJornada={seg.OrdemNaJornada} < anterior={prevOrdem}.");
            prevOrdem = seg.OrdemNaJornada;

            // (d) Cada segmento tem pelo menos um nó
            Assert.True(seg.Nos is { Count: > 0 },
                $"[{scenarioId}] Segmento etapa 7 ordemNaJornada={seg.OrdemNaJornada} " +
                $"(doPasso={seg.DoPasso}) está vazio — rasto ausente.");

            // (a) Cada nó tem ID não vazio
            foreach (var no in seg.Nos!)
            {
                Assert.False(string.IsNullOrWhiteSpace(no.Id),
                    $"[{scenarioId}] Nó com id vazio no segmento doPasso={seg.DoPasso}.");
            }

            // (c) Todos os nós do segmento que existem no percurso de referência
            //     aparecem numa ordem coerente (índice crescente ou igual no path).
            //     Nós de sub-processo podem não estar no path principal — são aceites.
            int prevRefIdx = -1;
            foreach (var no in seg.Nos!)
            {
                if (!ReferenceNodeOrder.TryGetValue(no.Id, out var refIdx))
                    continue; // nó de sub-processo ou não pertencente ao path principal

                Assert.True(refIdx >= prevRefIdx,
                    $"[{scenarioId}] Nó '{no.Id}' (refIdx={refIdx}) fora de ordem " +
                    $"no segmento doPasso={seg.DoPasso} — desvio no passo {refIdx + 1}.");
                prevRefIdx = refIdx;
            }
        }

        var totalNodes = etapa7Segments.SelectMany(s => s.Nos!).Count();
        _output.WriteLine(
            $"[ok] {scenarioId}: {etapa7Segments.Count} segmento(s) de etapa 7, " +
            $"{totalNodes} nós — todos estruturalmente válidos.");
    }

    // =========================================================================
    // AC2 — cobertura total: o nó do segmento etapa 7 é coberto em conjunto
    //        pelos cenários POC_EpatProcess de etapa 7
    // =========================================================================

    [Fact]
    public void Etapa7_POCEpatProcess_Coverage_AllEtapa7ReferenceNodesVisitedAcrossScenarios()
    {
        var pocScenarios = Etapa7Scenarios
            .Where(s => s.Process == "POC_EpatProcess")
            .ToList();

        var coveredIds = new HashSet<string>(StringComparer.Ordinal);

        foreach (var summary in pocScenarios)
        {
            var detail = ScenarioFixtureLoader.LoadScenario(summary.Id);
            var etapa7Nodes = (detail.Segmentos ?? [])
                .Where(s => s.Etapas != null && s.Etapas.Contains(7))
                .SelectMany(s => s.Nos ?? [])
                .Select(n => n.Id)
                .Where(id => !string.IsNullOrWhiteSpace(id));

            foreach (var id in etapa7Nodes)
                coveredIds.Add(id!);
        }

        var missing = Etapa7ReferenceNodeIds
            .Where(id => !coveredIds.Contains(id))
            .ToList();

        if (missing.Count > 0)
        {
            var details = string.Join(", ", missing.Select(id =>
            {
                var idx = ReferenceNodeOrder.TryGetValue(id, out var i) ? i + 1 : -1;
                return $"passo {idx}: '{id}'";
            }));
            Assert.Fail(
                $"Os seguintes nós canónicos da etapa 7 não foram cobertos por nenhum cenário: {details}");
        }

        _output.WriteLine(
            $"[ok] Todos os {Etapa7ReferenceNodeIds.Count} nós de referência da etapa 7 " +
            $"são cobertos pelos {pocScenarios.Count} cenários POC_EpatProcess.");
    }

    // =========================================================================
    // AC1 — fixture permanece imutável
    // =========================================================================

    /// <summary>
    /// AC1 — Confirma que nenhum dos 47 cenários POC_EpatProcess de etapa 7
    /// tem o campo 'path' nulo ou vazio no ficheiro de detalhe
    /// (o rasto vem da fixture, não do arnes).
    /// A ausência de escrita é garantida pela arquitectura do arnes (leitura pura).
    /// </summary>
    [Theory]
    [MemberData(nameof(Etapa7PocEpatScenarioIds))]
    public void Etapa7_Scenario_FixtureIsReadOnly_PathFieldNotWrittenByHarness(string scenarioId)
    {
        var detail = ScenarioFixtureLoader.LoadScenario(scenarioId);

        var hasSomeTrace = (detail.Path is { Count: > 0 })
            || (detail.Segmentos is { Count: > 0 });

        Assert.True(hasSomeTrace,
            $"[{scenarioId}] Fixture sem rasto (path[] vazio e segmentos[] vazio) — " +
            "a fixture deve vir do kit, não ser escrita pelo arnes.");

        _output.WriteLine(
            $"[ok] {scenarioId}: fixture contém rasto — " +
            $"path={detail.Path?.Count ?? 0} nós, segmentos={detail.Segmentos?.Count ?? 0}.");
    }

    // =========================================================================
    // AC4 — divergência reportada por caso e por passo com identificação exata
    //        Valida que o mecanismo de diagnóstico do arnes identifica a posição
    //        exata de uma divergência hipotética no rasto.
    // =========================================================================

    /// <summary>
    /// AC4 — Confirma que o percurso de referência contém o nó 'Fim'
    /// (passo 37) na posição 36 (0-based). Uma divergência neste passo deve ser
    /// imediatamente identificável porque o índice de referência é 36 e o nome do
    /// nó é 'Fim'.
    ///
    /// Rastreia: confidence.basis = "o oráculo é o cenário derivado do grafo;
    /// não há interpretação no arnes".
    /// </summary>
    [Fact]
    public void ReferenceScenario_Fim_AtExpectedPosition_EnablesPreciseDivergenceReport()
    {
        var path = ReferenceScenario.Path!;

        Assert.True(ReferenceNodeOrder.TryGetValue("_H22mclqWEfG5K7mY0I3I6w", out var refIdx),
            "Nó 'Fim' (_H22mclqWEfG5K7mY0I3I6w) ausente no path[] — " +
            "AC4: não é possível reportar divergência por posição.");

        Assert.Equal(36, refIdx);

        var node = path[refIdx];
        Assert.Equal("Fim", node.Nome);
        Assert.Equal("endEvent", node.Tipo);

        _output.WriteLine(
            $"[ok] 'Fim' em posição {refIdx} (passo {refIdx + 1}) — " +
            "divergência neste passo seria reportada como 'passo 37: Fim'.");
    }

    // =========================================================================
    // AC2 — sequência prepSub→ControlarIntimados→Fim bate com o path[]
    // =========================================================================

    /// <summary>
    /// AC2 — Confirma que os passos finais do percurso de referência estão na
    /// ordem correcta: prepSub (passo 35) → Controlar Intimados (passo 36) → Fim (passo 37).
    ///
    /// Rastreia: acceptance.criteria[0] e segmento ordemNaJornada=10 (etapa 7).
    /// </summary>
    [Fact]
    public void ReferenceScenario_FinalSequence_PrepSub_ControlarIntimados_Fim_IsInCorrectOrder()
    {
        const string prepSubId         = "_zE3XeV6JEfGBBLgT-R5iuw";   // passo 35
        const string controlarId       = "_nQntZ16JEfGBBLgT-R5iuw";   // passo 36
        const string fimId             = "_H22mclqWEfG5K7mY0I3I6w";   // passo 37

        Assert.True(ReferenceNodeOrder.TryGetValue(prepSubId,   out var prepSubIdx),
            $"'prepSub' ({prepSubId}) ausente no path[].");
        Assert.True(ReferenceNodeOrder.TryGetValue(controlarId, out var controlarIdx),
            $"'Controlar Intimados' ({controlarId}) ausente no path[].");
        Assert.True(ReferenceNodeOrder.TryGetValue(fimId,       out var fimIdx),
            $"'Fim' ({fimId}) ausente no path[].");

        Assert.True(prepSubIdx < controlarIdx,
            $"prepSub (idx={prepSubIdx}) deve preceder Controlar Intimados (idx={controlarIdx}).");
        Assert.True(controlarIdx < fimIdx,
            $"Controlar Intimados (idx={controlarIdx}) deve preceder Fim (idx={fimIdx}).");

        var path = ReferenceScenario.Path!;
        Assert.Equal("scriptTask",   path[prepSubIdx].Tipo);
        Assert.Equal("callActivity", path[controlarIdx].Tipo);
        Assert.Equal("endEvent",     path[fimIdx].Tipo);

        _output.WriteLine(
            $"[ok] passo {prepSubIdx + 1}→{controlarIdx + 1}→{fimIdx + 1}: " +
            $"prepSub → Controlar Intimados → Fim — ordem correcta.");
    }
}
